func (FfiConverterNetwork) Read(reader io.Reader) Network {
	id := readInt32(reader)
	switch id {
	case 1:
		return NetworkMainnet{}
	case 2:
		return NetworkTestnet{}
	case 3:
		return NetworkRegtest{
			FfiConverterActivationHeightsINSTANCE.Read(reader),
		}
	default:
		panic(fmt.Sprintf("invalid enum value %v in FfiConverterNetwork.Read()", id))
	}
}

