// The error type of every fallible call in this crate.
//
// Variants that the caller is expected to branch on carry their data in
// fields. The remaining variants carry a message only.
type WalletError struct {
	err error
}

// Convenience method to turn *WalletError into error
// Avoiding treating nil pointer as non nil error interface
func (err *WalletError) AsError() error {
	if err == nil {
		return nil
	} else {
		return err
	}
}

func (err WalletError) Error() string {
	return fmt.Sprintf("WalletError: %s", err.err.Error())
}

func (err WalletError) Unwrap() error {
	return err.err
}

