var FfiConverterWalletErrorINSTANCE = FfiConverterWalletError{}

func (c FfiConverterWalletError) Lift(eb RustBufferI) *WalletError {
	return LiftFromRustBuffer[*WalletError](c, eb)
}

func (c FfiConverterWalletError) Lower(value *WalletError) C.RustBuffer {
	return LowerIntoRustBuffer[*WalletError](c, value)
}

func (c FfiConverterWalletError) LowerExternal(value *WalletError) ExternalCRustBuffer {
	return RustBufferFromC(LowerIntoRustBuffer[*WalletError](c, value))
}

func (c FfiConverterWalletError) Read(reader io.Reader) *WalletError {
	errorID := readUint32(reader)

	switch errorID {
	case 1:
		return &WalletError{&WalletErrorInvalidArgument{
			Message: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 2:
		return &WalletError{&WalletErrorDatabase{
			Message: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 3:
		return &WalletError{&WalletErrorSeedRequired{}}
	case 4:
		return &WalletError{&WalletErrorSeedNotRelevant{}}
	case 5:
		return &WalletError{&WalletErrorAccountNotFound{}}
	case 6:
		return &WalletError{&WalletErrorAddressGapLimit{
			Message: FfiConverterStringINSTANCE.Read(reader),
		}}
	case 7:
		return &WalletError{&WalletErrorChainContinuity{
			AtHeight: FfiConverterUint32INSTANCE.Read(reader),
			Message:  FfiConverterStringINSTANCE.Read(reader),
		}}
	case 8:
		return &WalletError{&WalletErrorRewindInvalid{
			RequestedHeight: FfiConverterUint32INSTANCE.Read(reader),
			SafeHeight:      FfiConverterOptionalUint32INSTANCE.Read(reader),
		}}
	case 9:
		return &WalletError{&WalletErrorScan{
			AtHeight: FfiConverterUint32INSTANCE.Read(reader),
			Message:  FfiConverterStringINSTANCE.Read(reader),
		}}
	case 10:
		return &WalletError{&WalletErrorInternal{
			Message: FfiConverterStringINSTANCE.Read(reader),
		}}
	default:
		panic(fmt.Sprintf("Unknown error code %d in FfiConverterWalletError.Read()", errorID))
	}
}

func (c FfiConverterWalletError) Write(writer io.Writer, value *WalletError) {
	switch variantValue := value.err.(type) {
	case *WalletErrorInvalidArgument:
		writeInt32(writer, 1)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Message)
	case *WalletErrorDatabase:
		writeInt32(writer, 2)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Message)
	case *WalletErrorSeedRequired:
		writeInt32(writer, 3)
	case *WalletErrorSeedNotRelevant:
		writeInt32(writer, 4)
	case *WalletErrorAccountNotFound:
		writeInt32(writer, 5)
	case *WalletErrorAddressGapLimit:
		writeInt32(writer, 6)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Message)
	case *WalletErrorChainContinuity:
		writeInt32(writer, 7)
		FfiConverterUint32INSTANCE.Write(writer, variantValue.AtHeight)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Message)
	case *WalletErrorRewindInvalid:
		writeInt32(writer, 8)
		FfiConverterUint32INSTANCE.Write(writer, variantValue.RequestedHeight)
		FfiConverterOptionalUint32INSTANCE.Write(writer, variantValue.SafeHeight)
	case *WalletErrorScan:
		writeInt32(writer, 9)
		FfiConverterUint32INSTANCE.Write(writer, variantValue.AtHeight)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Message)
	case *WalletErrorInternal:
		writeInt32(writer, 10)
		FfiConverterStringINSTANCE.Write(writer, variantValue.Message)
	default:
		_ = variantValue
		panic(fmt.Sprintf("invalid error value `%v` in FfiConverterWalletError.Write", value))
	}
}

type FfiDestroyerWalletError struct{}

func (_ FfiDestroyerWalletError) Destroy(value *WalletError) {
	switch variantValue := value.err.(type) {
	case WalletErrorInvalidArgument:
		variantValue.destroy()
	case WalletErrorDatabase:
		variantValue.destroy()
	case WalletErrorSeedRequired:
		variantValue.destroy()
	case WalletErrorSeedNotRelevant:
		variantValue.destroy()
	case WalletErrorAccountNotFound:
		variantValue.destroy()
	case WalletErrorAddressGapLimit:
		variantValue.destroy()
	case WalletErrorChainContinuity:
		variantValue.destroy()
	case WalletErrorRewindInvalid:
		variantValue.destroy()
	case WalletErrorScan:
		variantValue.destroy()
	case WalletErrorInternal:
		variantValue.destroy()
	default:
		_ = variantValue
		panic(fmt.Sprintf("invalid error value `%v` in FfiDestroyerWalletError.Destroy", value))
	}
}

